<?php

declare(strict_types=1);

namespace App\Domains\AcademicCommunication\Domain\Contracts;

use App\Domains\AcademicCommunication\Domain\References\AssessmentSummaryReference;

/**
 * Read-only gateway to the Assessment engine (SPR-012). Report cards are NOT
 * generated by the Assessment engine: it supplies the academic content and this
 * engine renders the official document.
 */
interface AssessmentContract
{
    /**
     * Assessment aggregates per subject for one student over one period.
     *
     * @return list<AssessmentSummaryReference>
     */
    public function studentAssessmentSummaries(
        string $schoolId,
        int|string $studentId,
        int|string $yearId,
        int|string $termId,
    ): array;
}
